test('配送先がなければ確定できず、カートのまま残る', async () => {
  const { orders, payments, service } = await setup();
  const order = await orders.get('o1');
  await orders.save({ ...order!, shippingAddress: undefined });
  await assert.rejects(service.checkout('o1'), ShippingAddressRequiredError);
  assert.equal((await orders.get('o1'))?.status, 'CART');
  assert.equal(payments.calls.length, 0);
});

if (order.status !== 'CART' && order.status !== 'PAYMENT_FAILED') {
  throw new InvalidOrderStateError(order);
}
// 配送先がないまま課金すると、発送できない注文の代金だけを受け取ることになる
if (!order.shippingAddress) throw new ShippingAddressRequiredError(order.id);

order.status = 'PENDING_PAYMENT';
await this.#orders.save(order);

// handler：本文から 2 項目だけを拾って、新しい changes を作る
const src = body as Record<string, unknown>;
const changes: OrderDetailsChanges = {};
if ('shippingAddress' in src) changes.shippingAddress = parseShippingAddress(src.shippingAddress);
if ('deliveryNote' in src) changes.deliveryNote = parseDeliveryNote(src.deliveryNote);

// service：型は実行時に効かないので、ここでも 2 項目だけを写す
if ('shippingAddress' in changes) order.shippingAddress = changes.shippingAddress;
if ('deliveryNote' in changes) order.deliveryNote = changes.deliveryNote;
